package net.officefloor.hq.app.person;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.MapKeyColumn;
import jakarta.persistence.OrderColumn;
import jakarta.persistence.Table;
import jakarta.persistence.Version;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.HashSet;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import net.officefloor.hq.app.claim.ClaimStatus;

/**
 * A person on a sheet, with a name and a dated grade (A, B or C): the first grade they were given
 * applies from the beginning of time, and each later one from its own date. The name is kept with surrounding spaces
 * removed and is unique on the sheet ignoring case, by its {@link #keyOf key}. Its version is raised on
 * every save, so an edit made from an older version is refused.
 */
@Entity
@Table(name = "person")
public class Person {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    @Column(name = "name_key", nullable = false)
    private String nameKey;

    /** The first grade the person was given: in force from the beginning of time. */
    @Column(name = "grade", nullable = false)
    private String grade;

    /** The grades recorded since the first, by the date each is in force from. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_grade", joinColumns = @JoinColumn(name = "person_id"))
    @MapKeyColumn(name = "from_date")
    @Column(name = "grade", nullable = false)
    private Map<LocalDate, String> gradesFrom = new TreeMap<>();

    /** The person's own terms in days; null when they have none and take their grade's terms. */
    @Column(name = "terms")
    private Integer terms;

    /** The person's contact, kept trimmed and lower-cased; null when they have none. Unique on the sheet. */
    @Column(name = "contact")
    private String contact;

    @Version
    @Column(name = "version", nullable = false)
    private long version;

    /** How many statements have been taken for the person. */
    @Column(name = "statement_count", nullable = false)
    private int statementCount;

    /** The last statement's due-total; null with no statement, or when it was n/a. */
    @Column(name = "statement_total", precision = 14, scale = 2)
    private BigDecimal statementTotal;

    /** The sheet's today when the last statement was taken; null with no statement. */
    @Column(name = "statement_date")
    private LocalDate statementDate;

    /** The date the person is retired from; null while they are not retired. */
    @Column(name = "retired_from")
    private LocalDate retiredFrom;

    /**
     * The person's holds, in the order they were added: their OPEN and PENDING claims dated within
     * one, unless bound by a statement, count in no live total.
     */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_hold", joinColumns = @JoinColumn(name = "person_id"))
    private List<Hold> holds = new ArrayList<>();

    /** The ids of the other people on the sheet the person has named as their patrons, in the order named. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_patron", joinColumns = @JoinColumn(name = "person_id"))
    @OrderColumn(name = "patron_order")
    @Column(name = "patron_id", nullable = false)
    private List<Long> patronIds = new ArrayList<>();

    /** The other names the person goes by, each unique on the sheet with the names by its key. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_alias", joinColumns = @JoinColumn(name = "person_id"))
    private Set<Alias> aliases = new HashSet<>();

    protected Person() {
    }

    public Person(String sheetId, String name, String grade, Integer terms, String contact) {
        this.sheetId = sheetId;
        setName(name);
        this.grade = grade;
        this.terms = terms;
        setContact(contact);
    }

    /** A contact as it is kept: surrounding spaces removed and lower-cased; null when blank or none. */
    public static String contactOf(String contact) {
        if (contact == null || contact.isBlank()) {
            return null;
        }
        return contact.trim().toLowerCase(Locale.ROOT);
    }

    /** The name as it is kept: surrounding spaces removed. */
    public static String clean(String name) {
        return name.trim();
    }

    /** The key a name is unique by on its sheet: kept as cleaned, ignoring case. */
    public static String keyOf(String name) {
        return clean(name).toLowerCase(Locale.ROOT);
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = clean(name);
        this.nameKey = keyOf(name);
    }

    /** The first grade the person was given: in force from the beginning of time. */
    public String getGrade() {
        return grade;
    }

    /** The grades recorded since the first, by the date each is in force from, earliest first. */
    public Map<LocalDate, String> getGradesFrom() {
        return Collections.unmodifiableMap(new TreeMap<>(gradesFrom));
    }

    /**
     * The grade in force on a date: the one recorded from the latest date on or before it, else the
     * first grade the person was given.
     */
    public String gradeOn(LocalDate date) {
        String on = grade;
        LocalDate latest = null;
        for (Map.Entry<LocalDate, String> entry : gradesFrom.entrySet()) {
            if (!entry.getKey().isAfter(date) && (latest == null || entry.getKey().isAfter(latest))) {
                latest = entry.getKey();
                on = entry.getValue();
            }
        }
        return on;
    }

    /** Record a grade from a date, in place of any recorded from that same date. */
    public void gradeFrom(String grade, LocalDate from) {
        gradesFrom.put(from, grade);
    }

    /** The person's own terms in days; null when they have none. */
    public Integer getTerms() {
        return terms;
    }

    /** Set the person's own terms in days; null for none. */
    public void setTerms(Integer terms) {
        this.terms = terms;
    }

    /** The person's contact; null when they have none. */
    public String getContact() {
        return contact;
    }

    /** Set the person's contact, kept as {@link #contactOf cleaned}; blank or null for none. */
    public void setContact(String contact) {
        this.contact = contactOf(contact);
    }

    public long getVersion() {
        return version;
    }

    public int getStatementCount() {
        return statementCount;
    }

    public BigDecimal getStatementTotal() {
        return statementTotal;
    }

    public LocalDate getStatementDate() {
        return statementDate;
    }

    public LocalDate getRetiredFrom() {
        return retiredFrom;
    }

    /** Retire the person from a date: no claim dated after it can be added for them. */
    public void retire(LocalDate from) {
        this.retiredFrom = from;
    }

    /** Whether the person has any hold, whatever its dates. */
    public boolean isHeld() {
        return !holds.isEmpty();
    }

    public List<Hold> getHolds() {
        return Collections.unmodifiableList(holds);
    }

    /** Add a hold from a date, to a date (inclusive) or with no end. */
    public void hold(LocalDate from, LocalDate to) {
        holds.add(new Hold(from, to));
    }

    /** Whether a date falls within any of the person's holds. */
    public boolean heldOn(LocalDate date) {
        return holds.stream().anyMatch(hold -> hold.covers(date));
    }

    /** Whether the person's retirement date is reached on this date (the sheet's today). */
    public boolean retiredOn(LocalDate today) {
        return retiredFrom != null && today != null && !today.isBefore(retiredFrom);
    }

    /**
     * Whether an OPEN or PENDING claim of the person dated on this date, not bound by a statement, is
     * left out of the live totals on the sheet's today: when dated within a hold, or once the
     * person's retirement date is reached.
     */
    public boolean leavesLive(LocalDate date, LocalDate today) {
        return heldOn(date) || retiredOn(today);
    }

    /**
     * Whether a claim of the person in this status, dated on this date and bound by a statement or
     * not, counts in a live total on the sheet's today: OPEN, PENDING and SETTLED claims do, but not an
     * OPEN or PENDING one dated within a hold or once the person's retirement date is reached, unless a
     * statement has bound it, nor one deferred on the sheet's today.
     */
    public boolean countsLive(ClaimStatus status, LocalDate date, boolean stated, boolean deferred, LocalDate today) {
        return status.counts() && !deferred && !(status.isOpen() && !stated && leavesLive(date, today));
    }

    /** Whether a claim may be dated on this date: not after the person's retirement. */
    public boolean canClaimOn(LocalDate date) {
        return retiredFrom == null || !date.isAfter(retiredFrom);
    }

    /** Record a statement taken on a date with its due-total (null when n/a). */
    public void stated(BigDecimal total, LocalDate date) {
        this.statementCount++;
        this.statementTotal = total;
        this.statementDate = date;
    }

    /**
     * Cancel the last statement: one fewer is counted, and the one before it (its due-total, null
     * when n/a, and date) is shown again; with none before it, no statement is shown.
     */
    public void unstated(BigDecimal previousTotal, LocalDate previousDate) {
        this.statementCount--;
        this.statementTotal = previousTotal;
        this.statementDate = previousDate;
    }

    /** The ids of the person's patrons, in the order they were named. */
    public List<Long> getPatronIds() {
        return Collections.unmodifiableList(patronIds);
    }

    /** The person's aliases, sorted as names are compared. */
    public List<String> getAliases() {
        return aliases.stream().sorted(java.util.Comparator.comparing(Alias::getAliasKey).thenComparing(Alias::getAlias))
                .map(Alias::getAlias).toList();
    }

    /** Whether the person goes by this name or alias, compared as names are. */
    public boolean goesBy(String name) {
        String key = keyOf(name);
        return nameKey.equals(key) || aliases.stream().anyMatch(alias -> alias.getAliasKey().equals(key));
    }

    /** Add an alias, kept as names are kept. */
    public void addAlias(String alias) {
        aliases.add(new Alias(alias));
    }

    /** No longer name this person as a patron; false when they were not one. */
    public boolean removePatron(Long patronId) {
        return patronIds.remove(patronId);
    }

    /** Name another person as a patron; false when they already are one. */
    public boolean addPatron(Long patronId) {
        if (patronIds.contains(patronId)) {
            return false;
        }
        return patronIds.add(patronId);
    }
}
package net.officefloor.hq.app.person;

import java.util.Comparator;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.pool.PoolMember;
import net.officefloor.hq.app.pool.PoolMemberRepository;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleService;
import net.officefloor.hq.app.rollup.Rollups;
import net.officefloor.hq.app.sheet.SheetService;
import net.officefloor.hq.app.statement.StatementRepository;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * Merging a person into another on the sheet: a steward only. The merged person's claims move to the
 * other, numbers and dates kept, listed after the other's own in the order they were added, each
 * losing any figure a statement bound. Their name and aliases become aliases of the other; their
 * patrons are added to the other's (not the other themselves, no repeats); anyone naming them as a
 * patron names the other instead (no repeats); their pool memberships move to the other, shares added
 * where the other is already a member. Their statements, holds, watchers and contact are dropped, and
 * they leave the sheet.
 */
@Service
public class MergeService {

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final StatementRepository statements;
    private final WatchRepository watches;
    private final PoolMemberRepository poolMembers;
    private final RoleService roles;
    private final SheetService sheets;
    private final Rollups rollups;
    private final Audit audit;

    public MergeService(PersonRepository people, ClaimRepository claims, StatementRepository statements,
            WatchRepository watches, PoolMemberRepository poolMembers, RoleService roles, SheetService sheets,
            Rollups rollups, Audit audit) {
        this.people = people;
        this.claims = claims;
        this.statements = statements;
        this.watches = watches;
        this.poolMembers = poolMembers;
        this.roles = roles;
        this.sheets = sheets;
        this.rollups = rollups;
        this.audit = audit;
    }

    /**
     * Merge a person into another on the sheet: the person merged into, as the store holds them after.
     * Refused unless the user is a steward, for the person themselves, and when either is retired.
     */
    @Transactional
    public Person merge(String sheetId, String user, long personId, long intoId) {
        sheets.lock(sheetId);
        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward merges people.");
        }
        Person from = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
        Person into = people.findByIdAndSheetId(intoId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
        if (from.getId().equals(into.getId())) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "A person cannot be merged into themselves.");
        }
        if (from.getRetiredFrom() != null || into.getRetiredFrom() != null) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "A retired person cannot be merged.");
        }
        Rollups.Rollup before = rollups.take(sheetId);

        // Their claims, in the order they were added, move to the other unbound.
        List<Claim> moved = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, from.getId()).stream()
                .sorted(Comparator.comparing(Claim::getId)).toList();
        for (Claim claim : moved) {
            claim.reassign(into.getId());
            claim.unbind();
        }
        claims.saveAll(moved);

        // Their name and aliases become the other's aliases; their patrons the other's.
        into.addAlias(from.getName());
        from.getAliases().forEach(into::addAlias);
        for (Long patronId : from.getPatronIds()) {
            if (!patronId.equals(into.getId())) {
                into.addPatron(patronId);
            }
        }
        // Anyone naming them as a patron names the other instead.
        for (Person other : people.findBySheetIdOrderByIdAsc(sheetId)) {
            if (other.getId().equals(from.getId()) || !other.removePatron(from.getId())) {
                continue;
            }
            if (!other.getId().equals(into.getId())) {
                other.addPatron(into.getId());
            }
            people.save(other);
        }

        // Their pool memberships move to the other, shares added where the other is already a member.
        for (PoolMember member : poolMembers.findByPersonIdOrderByIdAsc(from.getId())) {
            PoolMember theirs = poolMembers.findByPoolIdAndPersonId(member.getPoolId(), into.getId()).orElse(null);
            if (theirs != null) {
                theirs.addShare(member.getShare());
                poolMembers.save(theirs);
                poolMembers.delete(member);
            } else {
                member.moveTo(into.getId());
                poolMembers.save(member);
            }
        }

        // Their statements and watchers are dropped, and they leave the sheet with their holds and contact.
        statements.deleteAll(statements.findBySheetIdAndPersonIdOrderBySeqDesc(sheetId, from.getId()));
        watches.deleteAll(watches.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, from.getId()));
        String fromName = from.getName();
        people.delete(from);
        people.flush();
        Person saved = people.saveAndFlush(into);

        // The moved claims are listed after the other's own, in the order they were added.
        moved.forEach(claim -> claims.relist(claim.getId()));

        audit.recordOnCommit("PERSON_MERGED sheet=" + sheetId + " by=" + user
                + " from=" + fromName + " into=" + saved.getName());
        rollups.audit(sheetId, user, before);
        return people.findByIdAndSheetId(intoId, sheetId).orElseThrow();
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollups;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The people kept on a sheet: listed, added and edited. */
@Service
public class PersonService {

    private final PersonRepository people;
    private final SheetService sheets;
    private final Rollups rollups;
    private final Audit audit;

    public PersonService(PersonRepository people, SheetService sheets, Rollups rollups, Audit audit) {
        this.people = people;
        this.sheets = sheets;
        this.rollups = rollups;
        this.audit = audit;
    }

    /** The sheet's people in the order they were added. */
    @Transactional(readOnly = true)
    public List<Person> list(String sheetId) {
        return people.findBySheetIdOrderByIdAsc(sheetId);
    }

    /**
     * Add a person to the sheet, with their own terms (null: none) and contact (null or blank: none);
     * refused when the name or the contact is already in use on it.
     */
    @Transactional
    public Person add(String sheetId, String user, String name, String grade, Integer terms, String contact) {
        sheets.load(sheetId);
        requireNameFree(sheetId, name, null);
        requireContactFree(sheetId, contact, null);
        Rollups.Rollup before = rollups.take(sheetId);
        Person person = people.saveAndFlush(new Person(sheetId, name, grade, terms, contact));
        audited("PERSON_ADDED", sheetId, user, person, sheets.today(sheetId), terms != null,
                person.getContact() != null);
        rollups.audit(sheetId, user, before);
        return person;
    }

    /**
     * Change a person's name and own terms (null: none) and record their grade from a date (null: the
     * sheet's today), keeping the grades already recorded, from the version of the person the editor loaded; refused when someone
     * has saved the person since, or when the name or contact (null or blank: none) is in use by another
     * person. PERSON_EDITED carries terms=&lt;terms&gt; and contact=&lt;contact&gt; only when the form gave
     * them or the edit changes them.
     */
    @Transactional
    public Person edit(String sheetId, String user, long personId, long version, String name, String grade,
            LocalDate gradeFrom, Integer terms, String contact, boolean termsGiven, boolean contactGiven) {
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
        if (person.getVersion() != version) {
            throw new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,
                    "Someone else has saved this person since it was opened.");
        }
        requireNameFree(sheetId, name, person.getId());
        requireContactFree(sheetId, contact, person.getId());
        Rollups.Rollup before = rollups.take(sheetId);
        LocalDate today = sheets.today(sheetId);
        boolean withTerms = termsGiven || !java.util.Objects.equals(person.getTerms(), terms);
        boolean withContact = contactGiven
                || !java.util.Objects.equals(person.getContact(), Person.contactOf(contact));
        person.setName(name);
        person.setTerms(terms);
        person.setContact(contact);
        person.gradeFrom(grade, gradeFrom != null ? gradeFrom : today);
        Person saved = people.saveAndFlush(person);
        audited("PERSON_EDITED", sheetId, user, saved, today, withTerms, withContact);
        rollups.audit(sheetId, user, before);
        return saved;
    }

    /**
     * Retire a person from a date; with no date, from the sheet's today. Once the sheet's today reaches
     * it, their OPEN and PENDING claims not bound by a statement leave the live totals.
     */
    @Transactional
    public Person retire(String sheetId, String user, long personId, LocalDate from) {
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
        Rollups.Rollup before = rollups.take(sheetId);
        person.retire(from != null ? from : sheets.today(sheetId));
        Person saved = people.saveAndFlush(person);
        audit.recordOnCommit("PERSON_RETIRED sheet=" + sheetId + " by=" + user
                + " name=" + saved.getName() + " from=" + saved.getRetiredFrom());
        rollups.audit(sheetId, user, before);
        return saved;
    }

    /**
     * Put a person on hold from a date (null: the sheet's today) to a date (null: no end); refused
     * when the to-date is before the from-date. Their figures and the sheet's totals move as their
     * OPEN and PENDING claims dated within it, not bound by a statement, leave the live totals.
     */
    @Transactional
    public Person hold(String sheetId, String user, long personId, LocalDate from, LocalDate to) {
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
        LocalDate start = from != null ? from : sheets.today(sheetId);
        if (to != null && to.isBefore(start)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A hold cannot end before it starts.");
        }
        Rollups.Rollup before = rollups.take(sheetId);
        person.hold(start, to);
        Person saved = people.saveAndFlush(person);
        audit.recordOnCommit("PERSON_HELD sheet=" + sheetId + " by=" + user
                + " name=" + saved.getName() + " from=" + start);
        rollups.audit(sheetId, user, before);
        return saved;
    }

    /**
     * Name another person on the sheet as a patron of this one; refused for the person themselves and
     * for someone already their patron.
     */
    @Transactional
    public Person addPatron(String sheetId, String user, long personId, long patronId) {
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
        Person patron = people.findByIdAndSheetId(patronId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such patron on this sheet."));
        if (person.getId().equals(patron.getId())) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "A person cannot be their own patron.");
        }
        if (!person.addPatron(patron.getId())) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That person is already a patron.");
        }
        Person saved = people.saveAndFlush(person);
        audit.recordOnCommit("PATRON_ADDED sheet=" + sheetId + " by=" + user
                + " name=" + saved.getName() + " patron=" + patron.getName());
        return saved;
    }

    /**
     * Give a person an alias; refused when it is blank, or when it equals, as names are compared, any
     * name or alias on the sheet.
     */
    @Transactional
    public Person addAlias(String sheetId, String user, long personId, String alias) {
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
        if (alias == null || alias.isBlank()) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "An alias is required.");
        }
        if (people.findBySheetIdAndName(sheetId, alias).isPresent()) {
            throw nameInUse();
        }
        person.addAlias(alias);
        Person saved = people.saveAndFlush(person);
        audit.recordOnCommit("PERSON_ALIAS_ADDED sheet=" + sheetId + " by=" + user
                + " name=" + saved.getName() + " alias=" + Person.clean(alias));
        return saved;
    }

    /**
     * Record the change to the person, with the grade in force on the sheet's today and, on an edit or
     * an add that gave them, their own terms and contact (blank when they have none), once it is committed.
     */
    private void audited(String event, String sheetId, String user, Person person, LocalDate today,
            boolean withTerms, boolean withContact) {
        audit.recordOnCommit(event + " sheet=" + sheetId + " by=" + user
                + " name=" + person.getName() + " grade=" + person.gradeOn(today)
                + (withTerms ? " terms=" + (person.getTerms() != null ? person.getTerms() : "") : "")
                + (withContact ? " contact=" + (person.getContact() != null ? person.getContact() : "") : ""));
    }

    /** Refuse a contact (null or blank: none) already held on the sheet by anyone other than {@code self}. */
    private void requireContactFree(String sheetId, String contact, Long self) {
        String kept = Person.contactOf(contact);
        if (kept == null) {
            return;
        }
        people.findBySheetIdAndContact(sheetId, kept)
                .filter(holder -> !holder.getId().equals(self))
                .ifPresent(holder -> {
                    throw new ResponseStatusException(HttpStatus.CONFLICT,
                            "That contact is already in use on this sheet.");
                });
    }

    /** Refuse a name already held on the sheet, as a name or an alias, by anyone other than {@code self}. */
    private void requireNameFree(String sheetId, String name, Long self) {
        people.findBySheetIdAndNameKey(sheetId, Person.keyOf(name))
                .filter(holder -> !holder.getId().equals(self))
                .ifPresent(holder -> {
                    throw nameInUse();
                });
        people.findBySheetIdAndAliasKey(sheetId, Person.keyOf(name))
                .filter(holder -> !holder.getId().equals(self))
                .ifPresent(holder -> {
                    throw nameInUse();
                });
    }

    static ResponseStatusException nameInUse() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "That name is already in use on this sheet.");
    }
}

